  "implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be a dict')
    if 'threshold' not in case:
        raise ValueError('missing threshold')
    if 'calls' not in case or not isinstance(case['calls'], list):
        raise ValueError('missing or invalid calls')
    threshold = case['threshold']
    if not isinstance(threshold, (int, float)):
        raise ValueError('threshold must be numeric')
    calls = case['calls']
    accepted_call_ids = []
    diagnostics = []
    for i, call in enumerate(calls):
        if not isinstance(call, dict):
            raise ValueError(f'call at index {i} is not a dict')
        required_fields = ['call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable']
        for f in required_fields:
            if f not in call:
                raise ValueError(f'missing field {f} in call at index {i}')
        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        pred_tokens = call['prediction_tokens']
        parseable = call['parseable']
        if not isinstance(loss_without, (int, float)) or not isinstance(loss_with, (int, float)):
            raise ValueError(f'non-numeric loss in call {call_id}')
        if not isinstance(pred_tokens, int) or pred_tokens <= 0:
            raise ValueError(f'prediction_tokens must be positive integer in call {call_id}')
        if not isinstance(parseable, bool):
            raise ValueError(f'parseable must be boolean in call {call_id}')
        gain = loss_without - loss_with
        normalized_gain = gain / pred_tokens
        normalized_gain_rounded = round(normalized_gain, 6)
        accepted = parseable and (normalized_gain >= threshold)
        diagnostics.append({
            'accepted': accepted,
            'call_id': call_id,
            'normalized_gain': normalized_gain_rounded
        })
        if accepted:
            accepted_call_ids.append(call_id)
    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }"
}
